mapper.select:
SELECT pu.id, pu.uid, pu.target_uid, pu.last_news, pu.create_time, pu.update_time, u1.nickname as uidName, u1.avatar as uidAvatar, u2.nickname as targetName, u2.avatar as targetAvatar, u2.occupation as targetOccupation FROM b_private_user AS pu LEFT JOIN b_user_main AS u1 ON pu.uid = u1.uuid LEFT JOIN b_user_main AS u2 ON pu.target_uid = u2.uuid
AND pu.uid = #{bo.uid}
AND pu.target_uid = #{bo.targetUid}
AND pu.last_news like concat('%', #{bo.lastNewsLike}, '%')
ORDER BY pu.update_time DESC, pu.create_time DESC
